def plan(tasks):
    if not tasks:
        return []

    # Build task lookup
    task_map = {}
    seen_ids = set()

    for t in tasks:
        tid = t["id"]
        if tid in seen_ids:
            raise ValueError(f"Duplicate task ID: {tid}")
        seen_ids.add(tid)
        task_map[tid] = t

    # Check for missing dependencies
    for t in tasks:
        for dep in t["deps"]:
            if dep not in seen_ids:
                raise ValueError(f"Missing dependency: {dep}")

    # Kahn's algorithm with priority-based selection
    # Compute in-degree for each task
    in_degree = {tid: 0 for tid in seen_ids}
    for t in tasks:
        for dep in t["deps"]:
            in_degree[t["id"]] += 1

    # Available tasks: in_degree == 0
    # Select by: highest priority, then smallest ID
    import heapq

    # Min-heap with (-priority, id) to get highest priority first, then smallest ID
    available = []
    for tid, deg in in_degree.items():
        if deg == 0:
            t = task_map[tid]
            heapq.heappush(available, (-t["priority"], tid))

    result = []
    while available:
        _, tid = heapq.heappop(available)
        result.append(tid)

        # Reduce in-degree of dependent tasks
        for t in tasks:
            if tid in t["deps"]:
                in_degree[t["id"]] -= 1
                if in_degree[t["id"]] == 0:
                    heapq.heappush(available, (-t["priority"], t["id"]))

    # Check for cycles: if result doesn't contain all tasks
    if len(result) != len(seen_ids):
        raise ValueError("Cycle detected in dependencies")

    return result

