#!/usr/bin/env python3
"""
tasks - a dependency-aware task manager (single file, Python stdlib only)
"""

import csv
import json
import os
import sys
from datetime import datetime
from typing import Optional

DATA_FILE = "tasks.json"


def load_tasks() -> list[dict]:
    """Load tasks from tasks.json. Returns empty list if file missing/empty/corrupt."""
    try:
        if not os.path.exists(DATA_FILE):
            return []
        with open(DATA_FILE, "r") as f:
            data = json.load(f)
        if not isinstance(data, list):
            return []
        return data
    except (json.JSONDecodeError, IOError):
        return []


def save_tasks(tasks: list[dict]) -> None:
    """Save tasks to tasks.json."""
    with open(DATA_FILE, "w") as f:
        json.dump(tasks, f, indent=2)


def get_next_id(tasks: list[dict]) -> int:
    """Get the next available task id (max id + 1)."""
    if not tasks:
        return 1
    return max(t["id"] for t in tasks) + 1


def find_task_by_id(tasks: list[dict], task_id: int) -> Optional[dict]:
    """Find a task by its id."""
    for t in tasks:
        if t["id"] == task_id:
            return t
    return None


def add_task(tasks: list[dict], title: str, priority: int = 3, deps: list[int] = None) -> tuple[bool, str]:
    """
    Add a task. Returns (success, message).
    Every dep must reference an existing task id.
    """
    if deps is None:
        deps = []

    # Validate all deps exist
    for dep_id in deps:
        if not find_task_by_id(tasks, dep_id):
            return False, f"dependency {dep_id} does not exist"

    new_id = get_next_id(tasks)
    new_task = {
        "id": new_id,
        "title": title,
        "priority": priority,
        "status": "open",
        "deps": deps,
        "created": datetime.now().isoformat()
    }
    tasks.append(new_task)
    save_tasks(tasks)
    return True, f"added task {new_id}: {title}"


def list_tasks(tasks: list[dict], status_filter: Optional[str] = None) -> list[dict]:
    """List tasks, optionally filtered by status."""
    if status_filter is None or status_filter == "all":
        return tasks
    return [t for t in tasks if t["status"] == status_filter]


def add_dependency(tasks: list[dict], task_id: int, other_id: int) -> tuple[bool, str]:
    """
    Add a dependency edge: task_id depends on other_id.
    Both must exist. Reject self-dependency.
    """
    if task_id == other_id:
        return False, "cannot add self-dependency"

    if not find_task_by_id(tasks, task_id):
        return False, f"task {task_id} does not exist"

    if not find_task_by_id(tasks, other_id):
        return False, f"task {other_id} does not exist"

    task = find_task_by_id(tasks, task_id)
    if other_id not in task["deps"]:
        task["deps"].append(other_id)
        save_tasks(tasks)
    return True, f"added dependency: {task_id} depends on {other_id}"


def mark_done(tasks: list[dict], task_id: int) -> tuple[bool, str]:
    """
    Mark a task done. If any deps are open, fail.
    """
    task = find_task_by_id(tasks, task_id)
    if not task:
        return False, f"task {task_id} does not exist"

    if task["status"] == "done":
        return True, f"task {task_id} is already done"

    # Check all deps are done
    for dep_id in task["deps"]:
        dep = find_task_by_id(tasks, dep_id)
        if dep and dep["status"] == "open":
            return False, f"cannot complete: blocked by open dependency {dep_id}"

    task["status"] = "done"
    save_tasks(tasks)
    return True, f"marked task {task_id} as done"


def remove_task(tasks: list[dict], task_id: int, force: bool = False) -> tuple[bool, str]:
    """
    Delete a task. If another task depends on it, refuse unless --force.
    If force, also remove from dependents' deps.
    """
    task = find_task_by_id(tasks, task_id)
    if not task:
        return False, f"task {task_id} does not exist"

    # Find tasks that depend on this one
    dependents = []
    for t in tasks:
        if task_id in t["deps"]:
            dependents.append(t)

    if dependents and not force:
        return False, f"cannot delete: {len(dependents)} task(s) depend on it"

    # Remove task
    tasks = [t for t in tasks if t["id"] != task_id]

    # Remove from dependents' deps if force
    if force:
        for t in tasks:
            if task_id in t["deps"]:
                t["deps"].remove(task_id)

    save_tasks(tasks)
    return True, f"deleted task {task_id}"


def get_ready_tasks(tasks: list[dict]) -> list[dict]:
    """
    Get open tasks whose deps are all done.
    Order by priority (highest first), then by id ascending.
    """
    ready = []
    for t in tasks:
        if t["status"] == "open":
            # Check all deps are done
            all_deps_done = True
            for dep_id in t["deps"]:
                dep = find_task_by_id(tasks, dep_id)
                if dep and dep["status"] == "open":
                    all_deps_done = False
                    break
            if all_deps_done:
                ready.append(t)

    # Sort by priority desc, then id asc
    ready.sort(key=lambda t: (-t["priority"], t["id"]))
    return ready


def get_plan(tasks: list[dict]) -> tuple[bool, str, list[int]]:
    """
    Print a valid execution order of ALL open tasks respecting dependencies.
    Returns (success, message, plan).
    Plan is list of task ids in execution order.
    """
    open_tasks = [t for t in tasks if t["status"] == "open"]

    if not open_tasks:
        return True, "no open tasks", []

    # Build adjacency: for each task, which tasks depend on it
    # We need to ensure each task appears after all its deps

    # Kahn's algorithm with priority ordering
    # First, compute in-degree (number of open deps)
    task_ids = {t["id"] for t in open_tasks}

    # Build dependency map for open tasks only
    deps_map = {}  # task_id -> list of dep_ids (that are also open)
    for t in open_tasks:
        deps_map[t["id"]] = [d for d in t["deps"] if d in task_ids]

    # In-degree: count of open deps
    in_degree = {tid: len(deps_map[tid]) for tid in task_ids}

    # Start with tasks that have no open deps
    # Sort by priority desc, then id asc
    ready = [tid for tid in task_ids if in_degree[tid] == 0]
    ready.sort(key=lambda tid: (-tasks_by_id(tasks, tid)["priority"], tid))

    plan = []
    while ready:
        # Take highest priority task
        ready.sort(key=lambda tid: (-tasks_by_id(tasks, tid)["priority"], tid))
        current = ready.pop(0)
        plan.append(current)

        # For each task that depends on current, decrement in-degree
        for tid in task_ids:
            if current in deps_map[tid]:
                in_degree[tid] -= 1
                if in_degree[tid] == 0 and tid not in plan:
                    ready.append(tid)

    # Check if we got all tasks
    if len(plan) != len(open_tasks):
        # Cycle detected - find it
        cycle = detect_cycle(tasks)
        return False, f"cycle detected: {cycle}", []

    return True, "plan generated", plan


def detect_cycle(tasks: list[dict]) -> list[int]:
    """Detect a cycle in the dependency graph among open tasks."""
    open_tasks = [t for t in tasks if t["status"] == "open"]
    task_ids = {t["id"] for t in open_tasks}

    # Build adjacency list (task -> tasks it depends on)
    adj = {}
    for t in open_tasks:
        adj[t["id"]] = [d for d in t["deps"] if d in task_ids]

    # DFS to find cycle
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {tid: WHITE for tid in task_ids}
    parent = {}

    def dfs(node, path):
        color[node] = GRAY
        for neighbor in adj.get(node, []):
            if color[neighbor] == GRAY:
                # Found cycle, reconstruct it
                cycle = [neighbor]
                curr = node
                while curr != neighbor:
                    cycle.append(curr)
                    curr = parent.get(curr)
                    if curr is None:
                        break
                cycle.append(neighbor)
                return sorted(cycle)
            elif color[neighbor] == WHITE:
                parent[neighbor] = node
                result = dfs(neighbor, path + [neighbor])
                if result:
                    return result
        color[node] = BLACK
        return None

    for tid in sorted(task_ids):
        if color[tid] == WHITE:
            result = dfs(tid, [tid])
            if result:
                return result

    return []


def get_blocking(tasks: list[dict], task_id: int) -> list[int]:
    """List which of the task's dependencies are still open."""
    task = find_task_by_id(tasks, task_id)
    if not task:
        return []

    blocking = []
    for dep_id in task["deps"]:
        dep = find_task_by_id(tasks, dep_id)
        if dep and dep["status"] == "open":
            blocking.append(dep_id)
    return blocking


def get_graph(tasks: list[dict]) -> dict[int, list[int]]:
    """
    Print each task with its direct dependents (reverse edges).
    Returns {task_id: [list of task_ids that depend on it]}
    """
    graph = {}
    for t in tasks:
        graph[t["id"]] = []

    for t in tasks:
        for dep_id in t["deps"]:
            if dep_id in graph:
                graph[dep_id].append(t["id"])

    return graph


def search_tasks(tasks: list[dict], term: str) -> list[dict]:
    """List tasks whose title contains term, case-insensitive."""
    term_lower = term.lower()
    return [t for t in tasks if term_lower in t["title"].lower()]


def get_stats(tasks: list[dict]) -> dict:
    """Print stats: total, open, done, ready, blocked, depth."""
    total = len(tasks)
    open_count = sum(1 for t in tasks if t["status"] == "open")
    done_count = sum(1 for t in tasks if t["status"] == "done")

    ready = get_ready_tasks(tasks)
    ready_count = len(ready)

    # Blocked: open tasks with at least one open dep
    blocked_count = 0
    for t in tasks:
        if t["status"] == "open":
            for dep_id in t["deps"]:
                dep = find_task_by_id(tasks, dep_id)
                if dep and dep["status"] == "open":
                    blocked_count += 1
                    break

    # Depth: longest dependency chain
    depth = compute_depth(tasks)

    return {
        "total": total,
        "open": open_count,
        "done": done_count,
        "ready": ready_count,
        "blocked": blocked_count,
        "depth": depth
    }


def compute_depth(tasks: list[dict]) -> int:
    """Compute the length of the longest dependency chain."""
    task_ids = {t["id"] for t in tasks}

    # Memoization
    memo = {}

    def get_depth(tid):
        if tid in memo:
            return memo[tid]
        task = find_task_by_id(tasks, tid)
        if not task or not task["deps"]:
            memo[tid] = 0
            return 0

        max_dep_depth = 0
        for dep_id in task["deps"]:
            if dep_id in task_ids:
                max_dep_depth = max(max_dep_depth, get_depth(dep_id))

        memo[tid] = max_dep_depth + 1
        return memo[tid]

    max_depth = 0
    for tid in task_ids:
        max_depth = max(max_depth, get_depth(tid))

    return max_depth


def export_csv(tasks: list[dict], filename: str) -> tuple[bool, str]:
    """Write all tasks to CSV."""
    try:
        with open(filename, "w", newline="") as f:
            writer = csv.writer(f)
            writer.writerow(["id", "title", "priority", "status", "deps"])
            for t in tasks:
                deps_str = ";".join(str(d) for d in t["deps"])
                writer.writerow([t["id"], t["title"], t["priority"], t["status"], deps_str])
        return True, f"exported to {filename}"
    except IOError as e:
        return False, f"export failed: {e}"


def import_csv(tasks: list[dict], filename: str) -> tuple[bool, str]:
    """
    Replace all current tasks with those loaded from CSV.
    Validate that every dep id referenced exists in the imported set.
    """
    try:
        with open(filename, "r", newline="") as f:
            reader = csv.reader(f)
            rows = list(reader)

        if not rows:
            return True, "imported 0 tasks (empty file)"

        # Skip header
        if rows[0] == ["id", "title", "priority", "status", "deps"]:
            data_rows = rows[1:]
        else:
            data_rows = rows

        new_tasks = []
        for row in data_rows:
            if len(row) < 5:
                continue
            task_id = int(row[0])
            title = row[1]
            priority = int(row[2])
            status = row[3]
            deps_str = row[4] if len(row) > 4 else ""
            deps = [int(d) for d in deps_str.split(";") if d.strip()]

            task = {
                "id": task_id,
                "title": title,
                "priority": priority,
                "status": status,
                "deps": deps,
                "created": datetime.now().isoformat()
            }
            new_tasks.append(task)

        # Validate deps exist within imported set
        task_ids = {t["id"] for t in new_tasks}
        for t in new_tasks:
            for dep_id in t["deps"]:
                if dep_id not in task_ids:
                    return False, f"import failed: dependency {dep_id} does not exist in imported set"

        tasks[:] = new_tasks
        save_tasks(tasks)
        return True, f"imported {len(new_tasks)} tasks"
    except (IOError, ValueError) as e:
        return False, f"import failed: {e}"


