def cmd_add(args: list[str]) -> tuple[bool, str]:
    """Handle 'add' command."""
    if len(args) < 1:
        return False, "add: missing title"

    title = args[0]
    priority = 3
    deps = []

    i = 1
    while i < len(args):
        if args[i] == "--priority":
            if i + 1 >= len(args):
                return False, "add: --priority requires a value"
            try:
                priority = int(args[i + 1])
                if priority < 1 or priority > 5:
                    return False, f"add: priority must be 1-5, got {priority}"
            except ValueError:
                return False, f"add: invalid priority {args[i + 1]}"
            i += 2
        elif args[i] == "--dep":
            if i + 1 >= len(args):
                return False, "add: --dep requires a value"
            try:
                dep_id = int(args[i + 1])
                deps.append(dep_id)
            except ValueError:
                return False, f"add: invalid dep id {args[i + 1]}"
            i += 2
        else:
            return False, f"add: unknown option {args[i]}"

    tasks = load_tasks()
    success, msg = add_task(tasks, title, priority, deps)
    return success, msg


def cmd_list(args: list[str]) -> tuple[bool, str]:
    """Handle 'list' command."""
    status_filter = None
    if len(args) >= 1:
        if args[0] in ("open", "done", "all"):
            status_filter = args[0]
        else:
            return False, f"list: invalid status {args[0]}"

    tasks = load_tasks()
    filtered = list_tasks(tasks, status_filter)

    if not filtered:
        return True, "no tasks"

    lines = []
    for t in filtered:
        marker = "[done]" if t["status"] == "done" else "[open]"
        deps_str = ";".join(str(d) for d in t["deps"])
        lines.append(f"{t['id']} {marker} {t['priority']} {t['title']} ({deps_str})")

    return True, "\n".join(lines)


def cmd_dep(args: list[str]) -> tuple[bool, str]:
    """Handle 'dep' command."""
    if len(args) < 1:
        return False, "dep: missing task id"

    task_id = None
    other_id = None

    i = 0
    while i < len(args):
        if args[i] == "--on":
            if i + 1 >= len(args):
                return False, "dep: --on requires a value"
            try:
                other_id = int(args[i + 1])
            except ValueError:
                return False, f"dep: invalid other_id {args[i + 1]}"
            i += 2
        else:
            if task_id is None:
                try:
                    task_id = int(args[i])
                except ValueError:
                    return False, f"dep: invalid task id {args[i]}"
            else:
                return False, f"dep: unexpected argument {args[i]}"
        i += 1

    if task_id is None or other_id is None:
        return False, "dep: missing task id or --on other_id"

    tasks = load_tasks()
    success, msg = add_dependency(tasks, task_id, other_id)
    return success, msg


def cmd_done(args: list[str]) -> tuple[bool, str]:
    """Handle 'done' command."""
    if len(args) < 1:
        return False, "done: missing task id"

    try:
        task_id = int(args[0])
    except ValueError:
        return False, f"done: invalid task id {args[0]}"

    tasks = load_tasks()
    success, msg = mark_done(tasks, task_id)
    return success, msg


def cmd_rm(args: list[str]) -> tuple[bool, str]:
    """Handle 'rm' command."""
    if len(args) < 1:
        return False, "rm: missing task id"

    task_id = None
    force = False

    i = 0
    while i < len(args):
        if args[i] == "--force":
            force = True
            i += 1
        else:
            if task_id is None:
                try:
                    task_id = int(args[i])
                except ValueError:
                    return False, f"rm: invalid task id {args[i]}"
            else:
                return False, f"rm: unexpected argument {args[i]}"
        i += 1

    if task_id is None:
        return False, "rm: missing task id"

    tasks = load_tasks()
    success, msg = remove_task(tasks, task_id, force)
    return success, msg


def cmd_ready(args: list[str]) -> tuple[bool, str]:
    """Handle 'ready' command."""
    tasks = load_tasks()
    ready = get_ready_tasks(tasks)

    if not ready:
        return True, "no ready tasks"

    lines = []
    for t in ready:
        deps_str = ";".join(str(d) for d in t["deps"])
        lines.append(f"{t['id']} {t['priority']} {t['title']} ({deps_str})")

    return True, "\n".join(lines)


def cmd_plan(args: list[str]) -> tuple[bool, str]:
    """Handle 'plan' command."""
    tasks = load_tasks()
    success, msg, plan = get_plan(tasks)

    if not success:
        return False, msg

    if not plan:
        return True, "no open tasks"

    lines = []
    for tid in plan:
        task = find_task_by_id(tasks, tid)
        lines.append(f"{tid} {task['priority']} {task['title']}")

    return True, "\n".join(lines)


def cmd_block(args: list[str]) -> tuple[bool, str]:
    """Handle 'block' command."""
    if len(args) < 1:
        return False, "block: missing task id"

    try:
        task_id = int(args[0])
    except ValueError:
        return False, f"block: invalid task id {args[0]}"

    tasks = load_tasks()
    blocking = get_blocking(tasks, task_id)

    if not blocking:
        return True, f"no open dependencies blocking task {task_id}"

    lines = []
    for dep_id in blocking:
        dep = find_task_by_id(tasks, dep_id)
        lines.append(f"{dep_id} {dep['title']}")

    return True, "\n".join(lines)


def cmd_graph(args: list[str]) -> tuple[bool, str]:
    """Handle 'graph' command."""
    tasks = load_tasks()
    graph = get_graph(tasks)

    lines = []
    for tid in sorted(graph.keys()):
        dependents = graph[tid]
        if dependents:
            lines.append(f"{tid}: {dependents}")
        else:
            lines.append(f"{tid}: (no dependents)")

    return True, "\n".join(lines)


def cmd_search(args: list[str]) -> tuple[bool, str]:
    """Handle 'search' command."""
    if len(args) < 1:
        return False, "search: missing term"

    term = args[0]
    tasks = load_tasks()
    results = search_tasks(tasks, term)

    if not results:
        return True, f"no tasks matching '{term}'"

    lines = []
    for t in results:
        deps_str = ";".join(str(d) for d in t["deps"])
        lines.append(f"{t['id']} {t['priority']} {t['title']} ({deps_str})")

    return True, "\n".join(lines)


def cmd_stats(args: list[str]) -> tuple[bool, str]:
    """Handle 'stats' command."""
    tasks = load_tasks()
    stats = get_stats(tasks)

    lines = [
        f"total: {stats['total']}",
        f"open: {stats['open']}",
        f"done: {stats['done']}",
        f"ready: {stats['ready']}",
        f"blocked: {stats['blocked']}",
        f"depth: {stats['depth']}"
    ]

    return True, "\n".join(lines)


def cmd_export(args: list[str]) -> tuple[bool, str]:
    """Handle 'export' command."""
    if len(args) < 1:
        return False, "export: missing filename"

    filename = args[0]
    tasks = load_tasks()
    success, msg = export_csv(tasks, filename)
    return success, msg


def cmd_import(args: list[str]) -> tuple[bool, str]:
    """Handle 'import' command."""
    if len(args) < 1:
        return False, "import: missing filename"

    filename = args[0]
    tasks = load_tasks()
    success, msg = import_csv(tasks, filename)
    return success, msg


def cmd_test(args: list[str]) -> tuple[bool, str]:
    """Handle 'test' command - run self-tests with temporary data file."""
    temp_file = "tasks_test.json"

    try:
        # Test 1: dep validation on add
        tasks = []
        success, msg = add_task(tasks, "Task A", 3, [999])
        assert not success, "should fail when dep doesn't exist"
        print("✓ dep validation on add")

        # Add a valid task
        success, msg = add_task(tasks, "Task A")
        assert success, "should succeed adding valid task"
        assert tasks[0]["id"] == 1
        print("✓ add task")

        # Test 2: done-blocking by open deps
        tasks = [{"id": 1, "title": "A", "priority": 3, "status": "open", "deps": [2], "created": ""}]
        success, msg = mark_done(tasks, 1)
        assert not success, "should fail when dep is open"
        assert "blocked" in msg.lower()
        print("✓ done-blocking by open deps")

        # Test 3: ready set
        tasks = [
            {"id": 1, "title": "A", "priority": 3, "status": "open", "deps": [], "created": ""},
            {"id": 2, "title": "B", "priority": 5, "status": "open", "deps": [], "created": ""},
            {"id": 3, "title": "C", "priority": 1, "status": "open", "deps": [], "created": ""}
        ]
        ready = get_ready_tasks(tasks)
        assert len(ready) == 3
        assert ready[0]["id"] == 2  # highest priority
        assert ready[1]["id"] == 1
        assert ready[2]["id"] == 3
        print("✓ ready set ordering")

        # Test 4: plan topological correctness
        tasks = [
            {"id": 1, "title": "A", "priority": 3, "status": "open", "deps": [], "created": ""},
            {"id": 2, "title": "B", "priority": 3, "status": "open", "deps": [1], "created": ""},
            {"id": 3, "title": "C", "priority": 3, "status": "open", "deps": [2], "created": ""}
        ]
        success, msg, plan = get_plan(tasks)
        assert success, "plan should succeed"
        assert plan == [1, 2, 3], f"plan should be [1,2,3], got {plan}"
        print("✓ plan topological correctness")

        # Test 5: cycle detection
        tasks = [
            {"id": 1, "title": "A", "priority": 3, "status": "open", "deps": [2], "created": ""},
            {"id": 2, "title": "B", "priority": 3, "status": "open", "deps": [1], "created": ""}
        ]
        success, msg, plan = get_plan(tasks)
        assert not success, "plan should fail with cycle"
        assert "cycle" in msg.lower()
        print("✓ cycle detection")

        # Test 6: rm-with-dependents
        tasks = [
            {"id": 1, "title": "A", "priority": 3, "status": "open", "deps": [], "created": ""},
            {"id": 2, "title": "B", "priority": 3, "status": "open", "deps": [1], "created": ""}
        ]
        success, msg = remove_task(tasks, 1)
        assert not success, "should fail when task has dependents"

        tasks = [
            {"id": 1, "title": "A", "priority": 3, "status": "open", "deps": [], "created": ""},
            {"id": 2, "title": "B", "priority": 3, "status": "open", "deps": [1], "created": ""}
        ]
        success, msg = remove_task(tasks, 1, force=True)
        assert success, "should succeed with --force"
        assert 1 not in tasks[0]["deps"], "dep should be removed from dependent"
        print("✓ rm-with-dependents and --force")

        # Test 7: stats depth
        tasks = [
            {"id": 1, "title": "A", "priority": 3, "status": "open", "deps": [], "created": ""},
            {"id": 2, "title": "B", "priority": 3, "status": "open", "deps": [1], "created": ""},
            {"id": 3, "title": "C", "priority": 3, "status": "open", "deps": [2], "created": ""}
        ]
        stats = get_stats(tasks)
        assert stats["depth"] == 3, f"depth should be 3, got {stats['depth']}"
        print("✓ stats depth")

        # Test 8: export/import round-trip
        tasks = [
            {"id": 1, "title": "A", "priority": 3, "status": "open", "deps": [], "created": ""},
            {"id": 2, "title": "B", "priority": 5, "status": "done", "deps": [1], "created": ""}
        ]
        success, msg = export_csv(tasks, temp_file)
        assert success, "export should succeed"

        tasks = []
        success, msg = import_csv(tasks, temp_file)
        assert success, "import should succeed"
        assert len(tasks) == 2, f"should have 2 tasks, got {len(tasks)}"
        print("✓ export/import round-trip")

        # Cleanup
        if os.path.exists(temp_file):
            os.remove(temp_file)

        print("all tests passed")
        return True, "all tests passed"

    except AssertionError as e:
        return False, f"test failed: {e}"
    except Exception as e:
        return False, f"test error: {e}"
    finally:
        # Cleanup temp file
        if os.path.exists(temp_file):
            try:
                os.remove(temp_file)
            except:
                pass


def main():
    if len(sys.argv) < 2:
        print_usage()
        sys.exit(1)

    command = sys.argv[1]
    args = sys.argv[2:]

    if command == "add":
        success, msg = cmd_add(args)
    elif command == "list":
        success, msg = cmd_list(args)
    elif command == "dep":
        success, msg = cmd_dep(args)
    elif command == "done":
        success, msg = cmd_done(args)
    elif command == "rm":
        success, msg = cmd_rm(args)
    elif command == "ready":
        success, msg = cmd_ready(args)
    elif command == "plan":
        success, msg = cmd_plan(args)
    elif command == "block":
        success, msg = cmd_block(args)
    elif command == "graph":
        success, msg = cmd_graph(args)
    elif command == "search":
        success, msg = cmd_search(args)
    elif command == "stats":
        success, msg = cmd_stats(args)
    elif command == "export":
        success, msg = cmd_export(args)
    elif command == "import":
        success, msg = cmd_import(args)
    elif command == "test":
        success, msg = cmd_test(args)
    else:
        print_usage()
        sys.exit(1)

    if not success:
        print(msg)
        sys.exit(1)

    print(msg)
    sys.exit(0)


if __name__ == "__main__":
    main()

